-- PostgreSQL translation of the embedded Arcade CMS schema.
-- Mechanical conversion only; no production database was changed.
-- Review enum/check semantics and installer placeholders before applying.

-- Extracted from arcade_cms/assets/includes/core.php
-- Source CMS schema/data definitions; MySQL/MariaDB syntax retained intentionally.

CREATE TABLE IF NOT EXISTS "gm_account" (
                "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                "name" text NOT NULL,
                "username" varchar(250) NOT NULL,
                "password" varchar(250) NOT NULL,
                "admin" text NOT NULL DEFAULT '0',
                "email" varchar(250) NOT NULL,
                "avatar_id" integer NOT NULL,
                "xp" integer NOT NULL,
                "language" varchar(250) NOT NULL,
                "profile_theme" varchar(250) NOT NULL DEFAULT 'style-1',
                "ip" varchar(250) NOT NULL,
                "registration_date" integer NOT NULL,
                "last_logged" integer NOT NULL,
                "last_update_info" integer NOT NULL,
                "active" text NOT NULL,
                PRIMARY KEY ("id") 
            );

CREATE TABLE IF NOT EXISTS "gm_users" (
                "user_id" integer NOT NULL,
                "gender" text NOT NULL DEFAULT '1',
                "about" text NOT NULL DEFAULT '', UNIQUE ("user_id")
            );

CREATE TABLE IF NOT EXISTS "gm_ads" (
                "id" integer NOT NULL,
                "728x90" varchar(700) NOT NULL,
                "300x250" varchar(700) NOT NULL,
                "600x300" varchar(700) NOT NULL,
                "728x90_main" varchar(700) NOT NULL,
                "300x250_main" varchar(700) NOT NULL,
                "ads_video" varchar(700) NOT NULL,
                PRIMARY KEY ("id")
            );

INSERT INTO "gm_ads" ("id", "728x90", "300x250", "600x300", "728x90_main", "300x250_main", "ads_video") VALUES (1, '', '', '', '', '', '');

CREATE TABLE IF NOT EXISTS "gm_categories" (
                "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                "category_pilot" varchar(250) NOT NULL,
                "name" text NOT NULL,
                "image" varchar(400) NOT NULL,
                "footer_description" TEXT NULL DEFAULT '',
                PRIMARY KEY ("id")
            );

