CREATE TABLE IF NOT EXISTS "gm_sliders" (
    "id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "type" varchar(100) NOT NULL,
    "category_tags_id" integer NOT NULL,
    "ordering" integer NOT NULL,
    PRIMARY KEY ("id")
);

